const productId = 5;
cy.request({
  method: "PUT",
  url: `${apiUrl}/orders/add`,
  headers: {
    Authorization: "Bearer " + token
  },
  body: {
    product: productId,
    quantity: 1
  }
}).then(response => {
  expect(response.status).to.eq(200);
  expect(response.body).to.have.property("orderLines").and.to.be.an("array");
  response.body.orderLines.forEach(line => {
    expect(line).to.have.property("quantity").and.to.be.a("number").and.to.be.greaterThan(0);
  });
});

const productId = 3; // Sentiments printaniers (stock -8)
cy.request(`${apiUrl}/products/${productId}`).then(res => {
  const stock = res.body.availableStock;
  expect(stock).to.be.at.most(0);
  cy.request({
    method: "PUT",
    url: `${apiUrl}/orders/add`,
    headers: {
      Authorization: "Bearer " + token
    },
    body: {
      product: productId,
      quantity: 1
    },
    failOnStatusCode: false
  }).then(res => {
    expect(res.status).to.not.eq(200); // Si le serveur renvoie 200, le test échoue
  });
});

const productId = 9;
cy.request(`${apiUrl}/products/${productId}`).then(res => {
  const stock = res.body.availableStock;
  expect(stock).to.be.a("number").and.to.be.greaterThan(0);
  const excessiveQuantity = stock + 1;
  cy.request({
    method: "PUT",
    url: `${apiUrl}/orders/add`,
    headers: {
      Authorization: "Bearer " + token
    },
    body: {
      product: productId,
      quantity: excessiveQuantity
    },
    failOnStatusCode: false
  }).then(res => {
    expect(res.status).to.not.eq(200);
  });
});

